--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
      BEGIN
          id, 
          email, 
          nombre, 
          cedula_ruc, 
          telefono, 
          rol, 
          estado,
          created_at, 
          updated_at
        )
        VALUES (
          new.id, 
          new.email, 
          COALESCE(
            NULLIF(TRIM(CONCAT(new.raw_user_meta_data->>'nombre', ' ', new.raw_user_meta_data->>'apellido')), ''),
            NULLIF(TRIM(new.raw_user_meta_data->>'nombre'), ''),
            NULLIF(TRIM(new.raw_user_meta_data->>'name'), ''),
            split_part(new.email, '@', 1),
            'Usuario'
          ),
          new.raw_user_meta_data->>'cedula',
          new.raw_user_meta_data->>'telefono',
          COALESCE(new.raw_user_meta_data->>'role', 'cliente'),
          'activo',
          COALESCE(new.created_at, NOW()),
          NOW()
        )
        ON CONFLICT (id) DO UPDATE SET
          email = EXCLUDED.email,
          nombre = COALESCE(EXCLUDED.nombre, public.usuarios.nombre),
          cedula_ruc = COALESCE(EXCLUDED.cedula_ruc, public.usuarios.cedula_ruc),
          telefono = COALESCE(EXCLUDED.telefono, public.usuarios.telefono),
          updated_at = NOW();

        RETURN new;
      EXCEPTION
        WHEN OTHERS THEN
          -- Log error as warning so user creation in auth.users NEVER fails
          RAISE WARNING 'handle_new_user failed for user %: %', new.id, SQLERRM;
          RETURN new;
      END;
      $$;


