    CONSTRAINT pasajero_pas_tipo_check CHECK (((pas_tipo)::text = ANY ((ARRAY['ADULT'::character varying, 'YOUTH'::character varying, 'CHILD'::character varying, 'INFANT'::character varying])::text[]))),
    CONSTRAINT pasajero_pas_tipodocumento_check CHECK (((pas_tipodocumento)::text = ANY ((ARRAY['PASSPORT'::character varying, 'NATIONAL_ID'::character varying])::text[])))
