CREATE TABLE public.tarifa_cabina (
    id_tarifa_cabina uuid DEFAULT gen_random_uuid() NOT NULL,
    tca_ofertaid uuid,
    tca_reservaid uuid,
    tca_itinerarioid uuid NOT NULL,
    tca_clasecabina character varying(20) NOT NULL,
    tca_marcatarifa character varying(50) NOT NULL,
    tca_asientosdisponibles smallint NOT NULL,
    tca_esreembolsable boolean NOT NULL,
    tca_esmodificable boolean NOT NULL,
    tca_moneda character varying(3) NOT NULL,
    tca_tarifabase numeric(12,2) NOT NULL,
    tca_impuestos numeric(12,2) NOT NULL,
    tca_total numeric(12,2) NOT NULL,
    tca_precioequipajeextra numeric(12,2) DEFAULT 0 NOT NULL,
    CONSTRAINT tarifa_cabina_check CHECK ((num_nonnulls(tca_ofertaid, tca_reservaid) = 1)),
    CONSTRAINT tarifa_cabina_check1 CHECK ((tca_total = (tca_tarifabase + tca_impuestos))),
    CONSTRAINT tarifa_cabina_tca_asientosdisponibles_check CHECK ((tca_asientosdisponibles >= 0)),
    CONSTRAINT tarifa_cabina_tca_clasecabina_check CHECK (((tca_clasecabina)::text = ANY ((ARRAY['ECONOMY'::character varying, 'PREMIUM_ECONOMY'::character varying, 'BUSINESS'::character varying, 'FIRST'::character varying])::text[]))),
    CONSTRAINT tarifa_cabina_tca_impuestos_check CHECK ((tca_impuestos >= (0)::numeric)),
    CONSTRAINT tarifa_cabina_tca_moneda_check CHECK (((tca_moneda)::text ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT tarifa_cabina_tca_precioequipajeextra_check CHECK ((tca_precioequipajeextra >= (0)::numeric)),
    CONSTRAINT tarifa_cabina_tca_tarifabase_check CHECK ((tca_tarifabase >= (0)::numeric)),
    CONSTRAINT tarifa_cabina_tca_total_check CHECK ((tca_total >= (0)::numeric))
);


