--
-- Name: vuelo; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.vuelo (
    id_vuelo uuid DEFAULT gen_random_uuid() NOT NULL,
    vue_numerovuelo character varying(10) NOT NULL,
    vue_fecha date NOT NULL,
    vue_aerolineamarketingid character varying(3) NOT NULL,
    vue_aerolineaoperadoraid character varying(3) NOT NULL,
    vue_aeropuertoorigen character varying(3) NOT NULL,
    vue_aeropuertodestino character varying(3) NOT NULL,
    vue_terminalorigen character varying(3),
    vue_terminaldestino character varying(3),
    vue_horasalidaprogramada timestamp with time zone NOT NULL,
    vue_horasalidaestimada timestamp with time zone,
    vue_horasalidareal timestamp with time zone,
    vue_horallegadaprogramada timestamp with time zone NOT NULL,
    vue_horallegadaestimada timestamp with time zone,
    vue_horallegadareal timestamp with time zone,
    vue_aeronave character varying(40),
    vue_duracionminutos integer,
    vue_estado character varying(20) DEFAULT 'SCHEDULED'::character varying NOT NULL,
    CONSTRAINT vuelo_check CHECK ((vue_horallegadaprogramada > vue_horasalidaprogramada)),
    CONSTRAINT vuelo_check1 CHECK (((vue_aeropuertoorigen)::text <> (vue_aeropuertodestino)::text)),
    CONSTRAINT vuelo_check2 CHECK (((vue_horasalidareal IS NULL) OR (vue_horasalidareal >= (vue_horasalidaprogramada - '12:00:00'::interval)))),
    CONSTRAINT vuelo_vue_aeropuertodestino_check CHECK (((vue_aeropuertodestino)::text ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT vuelo_vue_aeropuertoorigen_check CHECK (((vue_aeropuertoorigen)::text ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT vuelo_vue_duracionminutos_check CHECK ((vue_duracionminutos > 0)),
    CONSTRAINT vuelo_vue_estado_check CHECK (((vue_estado)::text = ANY ((ARRAY['SCHEDULED'::character varying, 'BOARDING'::character varying, 'DEPARTED'::character varying, 'DELAYED'::character varying, 'ARRIVED'::character varying, 'CANCELLED'::character varying, 'DIVERTED'::character varying])::text[]))),
    CONSTRAINT vuelo_vue_numerovuelo_check CHECK ((length(btrim((vue_numerovuelo)::text)) > 0))
);


ALTER TABLE public.vuelo OWNER TO postgres;

--
-- Name: vista_busqueda_vuelos; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vista_busqueda_vuelos AS
 SELECT vue.vue_numerovuelo,
    vue.vue_aeropuertoorigen,
    vue.vue_aeropuertodestino,
    vue.vue_fecha,
    vue.vue_horasalidaprogramada AS at,
    vue.vue_horallegadaprogramada,
    vue.vue_duracionminutos,
    amc.id_aerolinea AS marketingcarrier,
    aoc.id_aerolinea AS operatingcarrier,
    vue.vue_aeronave AS aircraft,
    vue.vue_estado AS status,
    vue.vue_terminalorigen AS departureterminal,
    vue.vue_terminaldestino AS arrivalterminal
   FROM ((public.vuelo vue
     JOIN public.aerolinea amc ON (((amc.id_aerolinea)::text = (vue.vue_aerolineamarketingid)::text)))
     JOIN public.aerolinea aoc ON (((aoc.id_aerolinea)::text = (vue.vue_aerolineaoperadoraid)::text)))
  WHERE ((vue.vue_estado)::text <> 'CANCELLED'::text);


ALTER VIEW public.vista_busqueda_vuelos OWNER TO postgres;

--
-- Name: vista_equipaje_pasajero; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vista_equipaje_pasajero AS
 SELECT eqp_pasajeroid AS passengerid,
    eqp_itineraryid AS itineraryid,
    eqp_moneda AS currency,
    max(eqp_precio) AS price,
    max(eqp_maximopermitido) AS maxallowed,
    (COALESCE(sum(eqp_cantidad), (0)::bigint))::integer AS alreadypurchased
   FROM public.equipaje_pasajero eqp
  GROUP BY eqp_pasajeroid, eqp_itineraryid, eqp_moneda;


ALTER VIEW public.vista_equipaje_pasajero OWNER TO postgres;

--
-- Name: vista_estado_vuelo_publico; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vista_estado_vuelo_publico AS
 SELECT vue.vue_numerovuelo AS "flightNumber",
    vue.vue_fecha AS date,
    amc.id_aerolinea AS "marketingCarrier",
    aoc.id_aerolinea AS "operatingCarrier",
    vue.vue_aeropuertoorigen AS "departure.iataCode",
    vue.vue_terminalorigen AS "departure.terminal",
    vue.vue_horasalidaprogramada AS "departure.scheduledAt",
    vue.vue_horasalidaestimada AS "departure.estimatedAt",
    vue.vue_horasalidareal AS "departure.actualAt",
    vue.vue_aeropuertodestino AS "arrival.iataCode",
    vue.vue_terminaldestino AS "arrival.terminal",
    vue.vue_horallegadaprogramada AS "arrival.scheduledAt",
    vue.vue_horallegadaestimada AS "arrival.estimatedAt",
    vue.vue_horallegadareal AS "arrival.actualAt",
    vue.vue_aeronave AS aircraft,
    vue.vue_estado AS status
   FROM ((public.vuelo vue
     JOIN public.aerolinea amc ON (((amc.id_aerolinea)::text = (vue.vue_aerolineamarketingid)::text)))
     JOIN public.aerolinea aoc ON (((aoc.id_aerolinea)::text = (vue.vue_aerolineaoperadoraid)::text)));


ALTER VIEW public.vista_estado_vuelo_publico OWNER TO postgres;

--
-- Name: vista_hold_estado; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vista_hold_estado AS
 SELECT id_bloqueo_cupo AS holdid,
    blo_estado AS status,
    blo_fechaexpiracion AS expiresat,
    GREATEST(0, (EXTRACT(epoch FROM (blo_fechaexpiracion - now())))::integer) AS remainingseconds,
    blo_ttlminutos AS ttlminutes,
    blo_moneda AS currency,
    blo_preciocongelado AS total
   FROM public.bloqueo_cupo blo
  WHERE ((blo_estado)::text = 'HELD'::text);


ALTER VIEW public.vista_hold_estado OWNER TO postgres;

--
-- Name: vista_listado_reservas; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vista_listado_reservas AS
 SELECT id_reserva AS bookingid,
    res_pnr AS pnr,
    res_estado AS status,
    ( SELECT vue.vue_aeropuertoorigen
           FROM ((public.reserva_segmento rsg
             JOIN public.reserva_itinerario ri ON ((ri.id_reserva_itinerario = rsg.rsg_itinerarioid)))
             JOIN public.vuelo vue ON ((vue.id_vuelo = rsg.rsg_vueloid)))
          WHERE (ri.rit_reservaid = r.id_reserva)
          ORDER BY ri.rit_orden, rsg.rsg_orden
         LIMIT 1) AS origin,
    ( SELECT vue.vue_aeropuertodestino
           FROM ((public.reserva_segmento rsg
             JOIN public.reserva_itinerario ri ON ((ri.id_reserva_itinerario = rsg.rsg_itinerarioid)))
             JOIN public.vuelo vue ON ((vue.id_vuelo = rsg.rsg_vueloid)))
          WHERE (ri.rit_reservaid = r.id_reserva)
          ORDER BY ri.rit_orden DESC, rsg.rsg_orden DESC
         LIMIT 1) AS destination,
    ( SELECT min(vue.vue_fecha) AS min
           FROM ((public.reserva_segmento rsg
             JOIN public.reserva_itinerario ri ON ((ri.id_reserva_itinerario = rsg.rsg_itinerarioid)))
             JOIN public.vuelo vue ON ((vue.id_vuelo = rsg.rsg_vueloid)))
          WHERE (ri.rit_reservaid = r.id_reserva)) AS departuredate,
    res_moneda AS currency,
    res_total AS grandtotal,
    res_fechacreacion AS createdat
   FROM public.reserva r;


ALTER VIEW public.vista_listado_reservas OWNER TO postgres;

--
-- Name: vista_mapa_asientos; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vista_mapa_asientos AS
 SELECT ose.osg_segmentid,
    asi.asi_clasecabina AS cabinclass,
    asi.asi_fila AS rownumber,
    json_agg(json_build_object('seatNumber', asi.asi_numeroasiento, 'isAvailable', asi.asi_estadisponible, 'characteristics', to_json(asi.asi_caracteristicas)) ORDER BY asi.asi_numeroasiento) AS seats
   FROM (public.asiento_vuelo asi
     JOIN public.oferta_segmento ose ON ((ose.osg_vueloid = asi.asi_vueloid)))
  GROUP BY ose.osg_segmentid, asi.asi_clasecabina, asi.asi_fila;


ALTER VIEW public.vista_mapa_asientos OWNER TO postgres;

--
-- Name: vista_ocupacion_vuelo; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vista_ocupacion_vuelo AS
 SELECT vue.id_vuelo,
    vue.vue_numerovuelo,
    vue.vue_fecha,
    vue.vue_aeropuertoorigen,
    vue.vue_aeropuertodestino,
    asi.asi_clasecabina,
    (count(*))::integer AS asientostotales,
    (count(*) FILTER (WHERE asi.asi_estadisponible))::integer AS asientoslibres,
    (count(*) FILTER (WHERE (NOT asi.asi_estadisponible)))::integer AS asientosocupados,
    ((count(*) FILTER (WHERE (NOT asi.asi_estadisponible)))::numeric / (NULLIF(count(*), 0))::numeric) AS ocupacionpct
   FROM (public.vuelo vue
     JOIN public.asiento_vuelo asi ON ((asi.asi_vueloid = vue.id_vuelo)))
  GROUP BY vue.id_vuelo, vue.vue_numerovuelo, vue.vue_fecha, vue.vue_aeropuertoorigen, vue.vue_aeropuertodestino, asi.asi_clasecabina;


ALTER VIEW public.vista_ocupacion_vuelo OWNER TO postgres;

--
-- Name: vista_oferta_segmento_api; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vista_oferta_segmento_api AS
 SELECT osg.osg_segmentid AS segmentid,
    vue.vue_numerovuelo AS flightnumber,
    vue.vue_aeropuertoorigen AS departureiatacode,
    vue.vue_horasalidaprogramada AS departureat,
    vue.vue_terminalorigen AS departureterminal,
    vue.vue_aeropuertodestino AS arrivaliatacode,
    vue.vue_horallegadaprogramada AS arrivalat,
    vue.vue_terminaldestino AS arrivalterminal,
    osg.osg_escalaminutos AS layoverminutes,
    amc.id_aerolinea AS marketingcarrier,
    aoc.id_aerolinea AS operatingcarrier,
    vue.vue_aeronave AS aircraft,
    vue.vue_duracionminutos AS durationminutes,
    osg.osg_estado AS status
   FROM (((public.oferta_segmento osg
     JOIN public.vuelo vue ON ((vue.id_vuelo = osg.osg_vueloid)))
     JOIN public.aerolinea amc ON (((amc.id_aerolinea)::text = (vue.vue_aerolineamarketingid)::text)))
     JOIN public.aerolinea aoc ON (((aoc.id_aerolinea)::text = (vue.vue_aerolineaoperadoraid)::text)));


ALTER VIEW public.vista_oferta_segmento_api OWNER TO postgres;

--
-- Name: vista_pases_abordar; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vista_pases_abordar AS
 SELECT res.id_reserva AS bookingid,
    json_agg(json_build_object('passengerId', pab.pab_pasajeroid, 'segmentId', pab.pab_segmentid, 'seat', pab.pab_asiento, 'boardingGroup', pab.pab_grupoabordaje, 'boardingPosition', pab.pab_posicionabordaje, 'barcode', pab.pab_codigobarras, 'barcodeType', pab.pab_tipocodigobarras) ORDER BY pab.pab_pasajeroid, pab.pab_segmentid) AS boardingpasses
   FROM ((public.pase_abordar pab
     JOIN public.boleto bol ON ((bol.id_boleto = pab.pab_boletoid)))
     JOIN public.reserva res ON ((res.id_reserva = bol.bol_reservaid)))
  WHERE ((bol.bol_estado)::text = 'ISSUED'::text)
  GROUP BY res.id_reserva;


ALTER VIEW public.vista_pases_abordar OWNER TO postgres;

--
-- Name: vista_reembolsos_financieros; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vista_reembolsos_financieros AS
 SELECT cco_moneda AS currency,
    (date_trunc('month'::text, cco_fechacancelacion))::date AS period,
    (count(DISTINCT cco_reservaid))::integer AS cancelaciones,
    COALESCE(sum(cco_montoreembolso), (0)::numeric) AS totalreembolsado,
    COALESCE(sum(cco_montopenalizacion), (0)::numeric) AS totalpenalizaciones,
    COALESCE(sum((cco_montoreembolso + cco_montopenalizacion)), (0)::numeric) AS netoretenido
   FROM public.cotizacion_cancelacion cco
  WHERE (((cco_estado)::text = 'CONSUMED'::text) AND (cco_fechacancelacion IS NOT NULL))
  GROUP BY cco_moneda, (date_trunc('month'::text, cco_fechacancelacion));


ALTER VIEW public.vista_reembolsos_financieros OWNER TO postgres;

